<?php
require __DIR__.'/config.php';
$u=require_login();
if(!is_super_admin()){http_response_code(403);exit('Super Admin only.');}
$pdo=db();
$b=null;
$tab=$_GET['tab']??'dashboard';
$allowed=['dashboard','businesses','payments','subscriptions','revenue','events','analytics','notifications','devices','audit','plans','settings'];
if(!in_array($tab,$allowed,true))$tab='dashboard';

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $action=$_POST['action']??'';
        if($action==='approve_payment'){
            $id=(int)($_POST['payment_id']??0);$s=$pdo->prepare("SELECT ps.*,b.name business_name,p.name plan_name,p.price plan_price FROM payment_submissions ps JOIN businesses b ON b.id=ps.business_id LEFT JOIN plans p ON p.id=ps.plan_id WHERE ps.id=? LIMIT 1");$s->execute([$id]);$ps=$s->fetch();if(!$ps||$ps['status']!=='pending')throw new RuntimeException('Payment submission is no longer pending.');
            $pdo->beginTransaction();
            $ends=date('Y-m-d H:i:s',strtotime('+1 month'));$s=$pdo->prepare("UPDATE subscriptions SET plan_id=?,plan='monthly',starts_at=NOW(),ends_at=?,grace_ends_at=NULL,status='active',amount=?,payment_reference=? WHERE id=? AND business_id=?");$s->execute([$ps['plan_id'],$ends,(float)$ps['amount'],$ps['payment_reference']?:null,$ps['subscription_id'],$ps['business_id']]);if($s->rowCount()===0)throw new RuntimeException('The subscription could not be activated.');
            $s=$pdo->prepare("UPDATE businesses SET account_status='active',status='active',updated_at=NOW() WHERE id=?");$s->execute([$ps['business_id']]);
            $s=$pdo->prepare("UPDATE payment_submissions SET status='approved',review_note=NULL,reviewed_by=?,reviewed_at=NOW(),updated_at=NOW() WHERE id=? AND status='pending'");$s->execute([$u['id'],$id]);
            $ref=$ps['payment_reference']?:'SERV-'.$id;$s=$pdo->prepare("INSERT INTO payment_transactions(business_id,subscription_id,type,amount,currency,status,reference,payer_name,payer_email,paid_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE status='successful',paid_at=NOW(),amount=VALUES(amount)");$s->execute([$ps['business_id'],$ps['subscription_id'],'subscription',(float)$ps['amount'],'NGN','offline',$ref,$ps['business_name'],$ps['owner_email']]);
            $pdo->commit();audit((int)$ps['business_id'],(int)$u['id'],'payment.approved','₦'.number_format((float)$ps['amount'],2).' · '.$ps['plan_name']);notify_business((int)$ps['business_id'],'SERV account activated','Your payment has been verified. Your SERV account is now active.',null,'onboarding.php','general');flash('Payment approved and account activated.');
        }elseif($action==='reject_payment'){
            $id=(int)($_POST['payment_id']??0);$note=trim((string)($_POST['review_note']??''));if($note==='')throw new RuntimeException('Please provide a rejection reason.');if(strlen($note)>1000)throw new RuntimeException('Rejection reason is too long.');$s=$pdo->prepare("SELECT ps.*,b.name business_name FROM payment_submissions ps JOIN businesses b ON b.id=ps.business_id WHERE ps.id=? LIMIT 1");$s->execute([$id]);$ps=$s->fetch();if(!$ps||$ps['status']!=='pending')throw new RuntimeException('Payment submission is no longer pending.');$s=$pdo->prepare("UPDATE payment_submissions SET status='rejected',review_note=?,reviewed_by=?,reviewed_at=NOW(),updated_at=NOW() WHERE id=? AND status='pending'");$s->execute([$note,$u['id'],$id]);audit((int)$ps['business_id'],(int)$u['id'],'payment.rejected',$note);notify_business((int)$ps['business_id'],'Payment needs attention','Your SERV payment proof was not approved. Please sign in to review the reason and submit a new proof.',null,'account.php','general');flash('Payment rejected. The business owner can resubmit proof.');
        }elseif($action==='save_payment_settings'){
            $vals=['payment_bank_name'=>trim((string)($_POST['payment_bank_name']??'')),'payment_account_name'=>trim((string)($_POST['payment_account_name']??'')),'payment_account_number'=>trim((string)($_POST['payment_account_number']??'')),'payment_instructions'=>trim((string)($_POST['payment_instructions']??''))];foreach($vals as $k=>$v){$ss=$pdo->prepare("INSERT INTO system_settings(setting_key,setting_value,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()");$ss->execute([$k,$v]);}audit(0,(int)$u['id'],'admin.payment_settings_saved','Payment account details updated');flash('Payment settings saved.');
        }elseif($action==='create_business'){
            $name=trim($_POST['name']??'');$type=$_POST['type']??'restaurant';$email=trim($_POST['email']??'');$pass=(string)($_POST['password']??'');
            if(!$name||!in_array($type,['restaurant','hotel','event_centre'],true)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Enter valid business and owner details.');
            $pdo->beginTransaction();
            $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).'-'.bin2hex(random_bytes(3));
            $s=$pdo->prepare("INSERT INTO businesses(name,type,slug,status,trial_ends_at,created_at) VALUES(?,?,?,?,?,NOW())");$s->execute([$name,$type,$slug,'active',date('Y-m-d H:i:s',time()+TRIAL_DAYS*86400)]);$bid=(int)$pdo->lastInsertId();
            $s=$pdo->prepare("INSERT INTO users(business_id,name,email,password_hash,role,status,created_at) VALUES(?,?,?,?, 'owner','active',NOW())");$s->execute([$bid,trim($_POST['owner_name']??'')?:'Owner',$email,password_hash($pass,PASSWORD_DEFAULT)]);
            $trialPlan=$pdo->query("SELECT id FROM plans WHERE code='starter' LIMIT 1")->fetchColumn();
            $s=$pdo->prepare("INSERT INTO subscriptions(business_id,plan_id,plan,starts_at,ends_at,status,amount) VALUES(?,?,?,?,?,?,?)");$s->execute([$bid,$trialPlan?:null,'trial',date('Y-m-d H:i:s'),date('Y-m-d H:i:s',time()+TRIAL_DAYS*86400),'active',0]);
            $pdo->commit();audit($bid,(int)$u['id'],'admin.business_created',$name.' ('.$type.')');flash('Business created successfully.');$tab='businesses';
        }elseif($action==='business_status'){
            $id=(int)$_POST['business_id'];$status=$_POST['status'];if(!in_array($status,['active','suspended','inactive'],true))throw new RuntimeException('Invalid status.');
            $s=$pdo->prepare('UPDATE businesses SET status=?,updated_at=NOW() WHERE id=?');$s->execute([$status,$id]);audit($id,(int)$u['id'],'admin.business_status',$status);flash('Business status updated.');
        }elseif($action==='extend_subscription'){
            $id=(int)$_POST['subscription_id'];$days=max(1,min(3650,(int)$_POST['days']));$s=$pdo->prepare("UPDATE subscriptions SET ends_at=DATE_ADD(GREATEST(COALESCE(ends_at,NOW()),NOW()),INTERVAL ? DAY),status='active' WHERE id=?");$s->execute([$days,$id]);flash('Subscription extended.');
        }elseif($action==='subscription_status'){
            $id=(int)$_POST['subscription_id'];$status=$_POST['status'];if(!in_array($status,['active','expired','cancelled','suspended'],true))throw new RuntimeException('Invalid subscription status.');$s=$pdo->prepare('UPDATE subscriptions SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Subscription status updated.');
        }elseif($action==='event_status'){
            $id=(int)$_POST['event_id'];$status=$_POST['status'];if(!in_array($status,['draft','scheduled','active','completed','cancelled'],true))throw new RuntimeException('Invalid event status.');$s=$pdo->prepare('UPDATE events SET status=?,updated_at=NOW() WHERE id=?');$s->execute([$status,$id]);flash('Event status updated.');
        }elseif($action==='save_plan'){
            $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$price=max(0,(float)($_POST['price']??0));$maxStaff=$_POST['max_staff']===''?null:max(0,(int)$_POST['max_staff']);$maxTables=$_POST['max_tables']===''?null:max(0,(int)$_POST['max_tables']);$maxRooms=$_POST['max_rooms']===''?null:max(0,(int)$_POST['max_rooms']);$maxMenu=$_POST['max_menu_items']===''?null:max(0,(int)$_POST['max_menu_items']);$maxServices=$_POST['max_services']===''?null:max(0,(int)$_POST['max_services']);$features=trim($_POST['features']??'');$status=in_array($_POST['status']??'active',['active','inactive'],true)?$_POST['status']:'active';$sort=max(0,(int)($_POST['sort_order']??0));
            if(!$name)throw new RuntimeException('Plan name is required.');
            if($id){$s=$pdo->prepare('UPDATE plans SET name=?,price=?,max_staff=?,max_tables=?,max_rooms=?,max_menu_items=?,max_services=?,features=?,status=?,sort_order=?,updated_at=NOW() WHERE id=?');$s->execute([$name,$price,$maxStaff,$maxTables,$maxRooms,$maxMenu,$maxServices,$features,$status,$sort,$id]);}else{$code=strtolower(trim(preg_replace('/[^a-z0-9]+/i','_',$_POST['code']??$name), '_'));$s=$pdo->prepare("INSERT INTO plans(name,code,product_type,price,max_staff,max_tables,max_rooms,max_menu_items,max_services,features,status,sort_order) VALUES(?,?, 'monthly',?,?,?,?,?,?,?,?,?)");$s->execute([$name,$code,$price,$maxStaff,$maxTables,$maxRooms,$maxMenu,$maxServices,$features,$status,$sort]);}
            audit(null,(int)$u['id'],'admin.plan_saved',$name.' · ₦'.number_format($price,2));flash('Monthly plan saved.');
        }elseif($action==='save_event_package'){
            $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$price=max(0,(float)($_POST['price']??0));$minGuests=max(1,(int)($_POST['min_guests']??1));$maxRaw=$_POST['max_guests']??'';$maxGuests=$maxRaw===''?null:max($minGuests,(int)$maxRaw);$features=trim($_POST['features']??'');$status=in_array($_POST['status']??'active',['active','inactive'],true)?$_POST['status']:'active';$sort=max(0,(int)($_POST['sort_order']??0));
            if(!$id||!$name)throw new RuntimeException('Package name is required.');
            $s=$pdo->prepare('UPDATE event_packages SET name=?,price=?,min_guests=?,max_guests=?,features=?,status=?,sort_order=?,updated_at=NOW() WHERE id=?');$s->execute([$name,$price,$minGuests,$maxGuests,$features,$status,$sort,$id]);audit(null,(int)$u['id'],'admin.event_package_saved',$name.' · ₦'.number_format($price,2));flash('Event/conference package saved.');
        }elseif($action==='save_setting'){
            $key=preg_replace('/[^a-z0-9_.-]/i','',$_POST['key']??'');$value=(string)($_POST['value']??'');if(!$key)throw new RuntimeException('Setting key is required.');$s=$pdo->prepare("INSERT INTO system_settings(setting_key,setting_value,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()");$s->execute([$key,$value]);flash('Setting saved.');
        }elseif($action==='send_notice'){
            $businessId=(int)($_POST['business_id']??0);$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');if(!$title||!$body)throw new RuntimeException('Title and message are required.');
            if($businessId){notify_business($businessId,$title,$body,null,'index.php','general');}else{$rows=$pdo->query("SELECT id FROM businesses WHERE status='active'")->fetchAll();foreach($rows as $r)notify_business((int)$r['id'],$title,$body,null,'index.php','general');}flash('Notification queued.');
        }
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Could not complete action: '.$e->getMessage(),'error');}
    redirect('admin.php?tab='.urlencode($tab));
}

function scalar(PDO $pdo,string $sql,array $p=[]){$s=$pdo->prepare($sql);$s->execute($p);return $s->fetchColumn();}
$totalBusinesses=(int)scalar($pdo,"SELECT COUNT(*) FROM businesses");$activeBusinesses=(int)scalar($pdo,"SELECT COUNT(*) FROM businesses WHERE status='active'");$hotels=(int)scalar($pdo,"SELECT COUNT(*) FROM businesses WHERE type='hotel'");$restaurants=(int)scalar($pdo,"SELECT COUNT(*) FROM businesses WHERE type='restaurant'");$venues=(int)scalar($pdo,"SELECT COUNT(*) FROM businesses WHERE type='event_centre'");
$activeSubs=(int)scalar($pdo,"SELECT COUNT(*) FROM subscriptions WHERE status='active' AND (ends_at IS NULL OR ends_at>=NOW())");$expiringSubs=(int)scalar($pdo,"SELECT COUNT(*) FROM subscriptions WHERE status='active' AND ends_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 7 DAY)");$expiredSubs=(int)scalar($pdo,"SELECT COUNT(*) FROM subscriptions WHERE status='expired' OR (status='active' AND ends_at<NOW())");
$totalEvents=(int)scalar($pdo,"SELECT COUNT(*) FROM events");$activeEvents=(int)scalar($pdo,"SELECT COUNT(*) FROM events WHERE status='active'");$eventGuests=(int)scalar($pdo,"SELECT COALESCE(SUM(guest_count),0) FROM events");$orders=(int)scalar($pdo,"SELECT COUNT(*) FROM orders");
$revenueMonth=(float)scalar($pdo,"SELECT COALESCE(SUM(amount),0) FROM payment_transactions WHERE status IN('successful','offline') AND created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')");$revenueYear=(float)scalar($pdo,"SELECT COALESCE(SUM(amount),0) FROM payment_transactions WHERE status IN('successful','offline') AND YEAR(created_at)=YEAR(NOW())");
$businesses=$pdo->query("SELECT b.*,u.name owner_name,u.email owner_email,(SELECT COUNT(*) FROM users us WHERE us.business_id=b.id) staff_count,(SELECT COUNT(*) FROM locations l WHERE l.business_id=b.id AND l.type='table' AND l.status='active') table_count,(SELECT COUNT(*) FROM locations l WHERE l.business_id=b.id AND l.type='room' AND l.status='active') room_count,(SELECT COUNT(*) FROM menu_items mi WHERE mi.business_id=b.id) menu_count,(SELECT COALESCE(SUM(o.total),0) FROM orders o WHERE o.business_id=b.id AND o.status<>'cancelled') sales FROM businesses b LEFT JOIN users u ON u.business_id=b.id AND u.role='owner' ORDER BY b.id DESC")->fetchAll();
$subs=$pdo->query("SELECT s.*,b.name business_name,b.type business_type,p.name plan_name FROM subscriptions s JOIN businesses b ON b.id=s.business_id LEFT JOIN plans p ON p.id=s.plan_id ORDER BY COALESCE(s.ends_at,'9999-12-31') ASC,s.id DESC")->fetchAll();
$events=$pdo->query("SELECT e.*,b.name business_name,p.name package_name,(SELECT COUNT(*) FROM event_guests g WHERE g.event_id=e.id) guests_actual,(SELECT COUNT(*) FROM event_tables t WHERE t.event_id=e.id) tables_actual FROM events e LEFT JOIN businesses b ON b.id=e.business_id LEFT JOIN event_packages p ON p.id=e.package_id ORDER BY e.event_date DESC,e.id DESC LIMIT 100")->fetchAll();
$plans=$pdo->query("SELECT * FROM plans ORDER BY product_type,sort_order,id")->fetchAll();$pendingPayments=(int)scalar($pdo,"SELECT COUNT(*) FROM payment_submissions WHERE status='pending'");$paymentRows=$pdo->query("SELECT ps.*,b.name business_name,b.type business_type,u.name owner_name,u.email owner_email,p.name plan_name FROM payment_submissions ps JOIN businesses b ON b.id=ps.business_id JOIN users u ON u.id=ps.user_id LEFT JOIN plans p ON p.id=ps.plan_id ORDER BY FIELD(ps.status,'pending','rejected','approved'),ps.id DESC LIMIT 100")->fetchAll();$recentAudit=$pdo->query("SELECT a.*,b.name business_name,u.name user_name FROM audit_logs a LEFT JOIN businesses b ON b.id=a.business_id LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 50")->fetchAll();$devices=(int)scalar($pdo,"SELECT COUNT(*) FROM device_tokens WHERE status='active'");$notifications=(int)scalar($pdo,"SELECT COUNT(*) FROM notification_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)");
include __DIR__.'/app/layout_top.php';
?>
<div class="page-head"><div><div class="eyebrow">SERV Control Centre</div><h1>Super Admin</h1><p>Platform operations, subscriptions, events and revenue.</p></div></div>
<div class="seg admin-tabs"><?php foreach(['dashboard'=>'Dashboard','businesses'=>'Businesses','payments'=>'Payments'.($pendingPayments?' · '.$pendingPayments:''),'subscriptions'=>'Subscriptions','revenue'=>'Revenue','events'=>'Events','analytics'=>'Analytics','notifications'=>'Notifications','devices'=>'Devices','audit'=>'Audit','plans'=>'Plans','settings'=>'Settings'] as $k=>$label):?><a class="<?=$tab===$k?'active':''?>" href="admin.php?tab=<?=$k?>"><?=e($label)?></a><?php endforeach;?></div>
