<div class="stats"><div class="panel"><span>Businesses</span><strong><?=$totalBusinesses?></strong></div><div class="panel"><span>Active</span><strong><?=$activeBusinesses?></strong></div><div class="panel"><span>Subscriptions</span><strong><?=$activeSubs?></strong></div><div class="panel"><span>Expiring 7d</span><strong><?=$expiringSubs?></strong></div><div class="panel"><span>Events</span><strong><?=$totalEvents?></strong></div><div class="panel"><span>Orders</span><strong><?=$orders?></strong></div></div>
<div class="stats"><div class="panel"><span>Restaurants</span><strong><?=$restaurants?></strong></div><div class="panel"><span>Hotels</span><strong><?=$hotels?></strong></div><div class="panel"><span>Event Centres</span><strong><?=$venues?></strong></div><div class="panel"><span>Event Guests</span><strong><?=$eventGuests?></strong></div><div class="panel"><span>Revenue Month</span><strong>₦<?=number_format($revenueMonth,0)?></strong></div><div class="panel"><span>Revenue Year</span><strong>₦<?=number_format($revenueYear,0)?></strong></div></div>
<div class="panel"><div class="section-head"><h3>Platform snapshot</h3><span class="badge">LIVE</span></div><div class="row"><span>Active devices</span><b><?=$devices?></b></div><div class="row"><span>Notifications last 30 days</span><b><?=$notifications?></b></div><div class="row"><span>Expired subscriptions</span><b><?=$expiredSubs?></b></div><div class="row"><span>Active events</span><b><?=$activeEvents?></b></div></div>
<?php elseif($tab==='businesses'):?>
<div class="panel"><h3>Create business</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create_business"><label>Business name<input name="name" required></label><label>Type<select name="type"><option value="restaurant">Restaurant</option><option value="hotel">Hotel</option><option value="event_centre">Event Centre</option></select></label><label>Owner name<input name="owner_name" required></label><label>Owner email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><div><button class="btn gold">Create business</button></div></form></div>
