<?php elseif($tab==='payments'):?>
<div class="stats"><div class="panel"><span>Awaiting verification</span><strong><?=$pendingPayments?></strong></div><div class="panel"><span>Approved</span><strong><?=number_format((int)scalar($pdo,"SELECT COUNT(*) FROM payment_submissions WHERE status='approved'"))?></strong></div><div class="panel"><span>Rejected</span><strong><?=number_format((int)scalar($pdo,"SELECT COUNT(*) FROM payment_submissions WHERE status='rejected'"))?></strong></div></div>
<div class="panel"><h3>Payment verification</h3><p class="small muted">Review the payment slip before activating the business account. Only Super Admin can approve or reject a submission.</p><?php foreach($paymentRows as $ps):?><div class="payment-admin-row"><div><b><?=e($ps['business_name'])?></b><div class="small muted"><?=e($ps['owner_name'])?> · <?=e($ps['owner_email'])?></div><div class="small muted"><?=e($ps['plan_name']??'Plan')?> · ₦<?=number_format((float)$ps['amount'],0)?> · <?=e(date('d M Y, H:i',strtotime($ps['submitted_at'])))?></div><div class="small muted">Reference: <?=e($ps['payment_reference']?:'Not provided')?></div></div><div class="right"><span class="status-pill status-<?=e($ps['status'])?>"><?=e(ucfirst($ps['status']))?></span><div class="actions"><a class="btn" target="_blank" rel="noopener" href="payment-proof.php?id=<?=$ps['id']?>">View slip</a><?php if($ps['status']==='pending'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_payment"><input type="hidden" name="payment_id" value="<?=$ps['id']?>"><button class="btn gold" type="submit">Approve & activate</button></form><form method="post" class="reject-form"><?=csrf_field()?><input type="hidden" name="action" value="reject_payment"><input type="hidden" name="payment_id" value="<?=$ps['id']?>"><input name="review_note" placeholder="Reason for rejection" required maxlength="1000"><button class="btn" type="submit">Reject</button></form><?php endif;?></div></div></div><?php endforeach;if(!$paymentRows):?><p class="muted">No payment submissions yet.</p><?php endif;?></div>
<?php elseif($tab==='subscriptions'):?>
<div class="stats"><div class="panel"><span>Active</span><strong><?=$activeSubs?></strong></div><div class="panel"><span>Expiring 7d</span><strong><?=$expiringSubs?></strong></div><div class="panel"><span>Expired</span><strong><?=$expiredSubs?></strong></div></div><div class="panel"><h3>Subscriptions</h3><?php foreach($subs as $s):?><div class="row"><div><b><?=e($s['business_name'])?></b><div class="small muted"><?=e($s['plan_name']??strtoupper($s['plan']))?> · <?=e($s['business_type'])?></div><div class="small muted">Ends: <?=e($s['ends_at']??'No expiry')?> · ₦<?=number_format((float)$s['amount'],0)?></div></div><div class="right"><span class="badge"><?=e(strtoupper($s['status']))?></span><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="extend_subscription"><input type="hidden" name="subscription_id" value="<?=$s['id']?>"><input type="number" name="days" value="30" min="1" max="3650" style="width:70px"><button class="btn">+ Days</button></form></div></div></div><?php endforeach;?></div>
<?php elseif($tab==='revenue'):?>
<div class="stats"><div class="panel"><span>This month</span><strong>₦<?=number_format($revenueMonth,0)?></strong></div><div class="panel"><span>This year</span><strong>₦<?=number_format($revenueYear,0)?></strong></div><div class="panel"><span>All time</span><strong>₦<?=number_format((float)scalar($pdo,"SELECT COALESCE(SUM(amount),0) FROM payment_transactions WHERE status IN('successful','offline')"),0)?></strong></div></div><div class="panel"><h3>Revenue by type</h3><?php $rev=$pdo->query("SELECT type,COUNT(*) transactions,COALESCE(SUM(amount),0) total FROM payment_transactions WHERE status IN('successful','offline') GROUP BY type ORDER BY total DESC")->fetchAll();foreach($rev as $r):?><div class="row"><span><?=e(ucfirst($r['type']))?> <span class="small muted">(<?=$r['transactions']?>)</span></span><b>₦<?=number_format((float)$r['total'],0)?></b></div><?php endforeach;?></div>
<?php elseif($tab==='events'):?>
